void ChangeMaxBrightness(lv_event_t * e)
{
	uint16_t curr_brightness;
	char txtd[25];
	curr_brightness = lv_slider_get_value(ui_MaxBrightnessCtrl);
	sysOpt.BacklightBrightness = curr_brightness;
	curr_brightness = curr_brightness * BL_PWM_RES / lv_slider_get_max_value(ui_MaxBrightnessCtrl);
	ledcWrite(BL_PWM, curr_brightness);
	curr_brightness = curr_brightness * 100 / BL_PWM_RES ; // Scaled value to 0 to 100% range to display
	sprintf(txtd, "Brightness: [%d%%]", curr_brightness);
	lv_label_set_text(ui_MaxBrightnessLbl, txtd);
	uiActions = true;
}

