void ChangeBacklightTout(lv_event_t * e)
{
	// Your code here
	uint16_t Timeout;
	char txtd[25];
	Timeout = lv_slider_get_value(ui_BacklightToutCtrl);
	sysOpt.BacklightTout = Timeout;
	if(Timeout == 0) 
		sprintf(txtd, "BL Timeout: [OFF]");
	else sprintf(txtd, "BL Timeout: [%d sec]", Timeout * 5);
	lv_label_set_text(ui_BacklightToutLbl, txtd);
	uiActions = true;
}

